    window.renderSystemOverview = renderSystemOverview;
    function buildOvwPaginationHtml(currentPage, totalItems, pageSize, onPageChangeFnName) {
      const totalPages = Math.ceil(totalItems / pageSize) || 1;
      if (totalPages <= 1) return "";
      let html = '<div style="display:flex; justify-content:center; align-items:center; gap:6px; margin-top:14px; padding:8px 0; flex-wrap:wrap; border-top:1px solid #1a2538;">';
      if (currentPage > 1) {
        html += '<button type="button" onclick="' + onPageChangeFnName + '(' + (currentPage - 1) + ')" style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#cbd5e1; border-radius:6px; font-size:0.75rem; cursor:pointer;"><i class="fa-solid fa-chevron-left"></i> Trước</button>';
      } else {
        html += '<button type="button" disabled style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.75rem; cursor:not-allowed; opacity:0.6;"><i class="fa-solid fa-chevron-left"></i> Trước</button>';
      }
      for (let i = 1; i <= totalPages; i++) {
        if (i === currentPage) {
          html += '<button type="button" style="padding:4px 9px; background:#0284c7; border:1px solid #0284c7; color:#fff; font-weight:700; border-radius:6px; font-size:0.75rem;">' + i + '</button>';
        } else if (i === 1 || i === totalPages || (i >= currentPage - 1 && i <= currentPage + 1)) {
          html += '<button type="button" onclick="' + onPageChangeFnName + '(' + i + ')" style="padding:4px 9px; background:#0d131f; border:1px solid #1e293b; color:#94a3b8; border-radius:6px; font-size:0.75rem; cursor:pointer;">' + i + '</button>';
        } else if (i === currentPage - 2 || i === currentPage + 2) {
          html += '<span style="color:#64748b; padding:0 3px; font-size:0.75rem;">...</span>';
        }
      }
      if (currentPage < totalPages) {
        html += '<button type="button" onclick="' + onPageChangeFnName + '(' + (currentPage + 1) + ')" style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#cbd5e1; border-radius:6px; font-size:0.75rem; cursor:pointer;">Sau <i class="fa-solid fa-chevron-right"></i></button>';
      } else {
        html += '<button type="button" disabled style="padding:4px 10px; background:#0d131f; border:1px solid #1e293b; color:#475569; border-radius:6px; font-size:0.75rem; cursor:not-allowed; opacity:0.6;">Sau <i class="fa-solid fa-chevron-right"></i></button>';
      }
      html += '<span style="font-size:0.72rem; color:#64748b; margin-left:6px;">(' + currentPage + '/' + totalPages + ' - ' + totalItems + ' mục)</span>';
      html += '</div>';
      return html;
    }
    window.buildOvwPaginationHtml = buildOvwPaginationHtml;
    function changeOvwPendingOrdersPage(p) {
      window._ovwPendingOrdersPage = Number(p) || 1;
      if (typeof renderSystemOverview === "function") renderSystemOverview();
    }
    window.changeOvwPendingOrdersPage = changeOvwPendingOrdersPage;
    function changeOvwPendingWithdrawPage(p) {
      window._ovwPendingWithdrawPage = Number(p) || 1;
      if (typeof renderSystemOverview === "function") renderSystemOverview();
    }
    window.changeOvwPendingWithdrawPage = changeOvwPendingWithdrawPage;
    function populateCategorySelects(selectedCat) {
      const select = document.getElementById("admProdCategory");
      if (!select) return;
      const cats = (MOCK_DATA && MOCK_DATA.categories) ? MOCK_DATA.categories : ["Gmail", "TikTok", "Facebook", "Rom & Tools", "Telegram", "Proxy", "AI & Video"];
      const validCats = cats.filter(c => c !== "Tất cả").map(c => c.replace(/&amp;/g, '&'));
      const normSelected = selectedCat ? String(selectedCat).replace(/&amp;/g, '&').toLowerCase() : "";
      let html = "";
      validCats.forEach(c => {
        const isSel = (normSelected && normSelected === c.toLowerCase()) ? "selected" : "";
        html += '<option value="' + escapeHtml(c).replace(/&amp;/g, '&') + '" ' + isSel + '>' + escapeHtml(c) + '</option>';
      });
      if (selectedCat && selectedCat !== "Tất cả" && !validCats.some(c => c.toLowerCase() === normSelected)) {
        const cleanSel = String(selectedCat).replace(/&amp;/g, '&');
        html += '<option value="' + escapeHtml(cleanSel).replace(/&amp;/g, '&') + '" selected>' + escapeHtml(cleanSel) + '</option>';
      }
      select.innerHTML = html;
      if (selectedCat) select.value = String(selectedCat).replace(/&amp;/g, '&');
    }
    window.populateCategorySelects = populateCategorySelects;
    function toggleAdmProductSourceFields() {
      const isApi = document.getElementById("admProdTypeApi")?.checked;
      const panel = document.getElementById("admProdApiConfigPanel");
      const badge = document.getElementById("admProdTypeBadge");
      if (panel) panel.style.display = isApi ? "block" : "none";
      if (badge) {
        if (isApi) {
          badge.innerHTML = '<i class="fa-solid fa-bolt"></i> Mua Qua API';
          badge.style.background = 'rgba(6,182,212,0.15)';
          badge.style.color = '#06b6d4';
          badge.style.borderColor = 'rgba(6,182,212,0.3)';
        } else {
          badge.innerHTML = '<i class="fa-solid fa-box"></i> Kho Nội Bộ';
          badge.style.background = 'rgba(16,185,129,0.15)';
          badge.style.color = '#10b981';
          badge.style.borderColor = 'rgba(16,185,129,0.3)';
        }
      }
      if (isApi) {
        handleAdmModalProviderChange();
      }
    }
    window.toggleAdmProductSourceFields = toggleAdmProductSourceFields;
    function filterAdmModalSourceProducts(keyword) {
      const pSel = document.getElementById("admProdApiProvider");
      const sSel = document.getElementById("admProdApiSourceSelect");
      const countSpan = document.getElementById("admSourceSearchCount");
      const clearBtn = document.getElementById("btnAdmClearSourceSearch");
      if (!sSel) return;
      const kw = (keyword || "").trim().toLowerCase();
      if (clearBtn) clearBtn.style.display = kw ? "inline-block" : "none";
      const provider = pSel ? (pSel.value || "shop1989nd") : "shop1989nd";
      const prods = (typeof window.cachedSourceProducts !== "undefined" && Array.isArray(window.cachedSourceProducts))
        ? window.cachedSourceProducts
        : ((typeof cachedSourceProducts !== "undefined" && Array.isArray(cachedSourceProducts)) ? cachedSourceProducts : []);
      let filtered = prods.filter(s => !s.provider || s.provider === provider);
      const totalInProvider = filtered.length;
      if (kw) {
        const removeAccents = function(str) {
          return String(str || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/Đ/g, "D");
        };
        const normKw = removeAccents(kw);
        const words = normKw.split(/\s+/).filter(Boolean);
        filtered = filtered.filter(s => {
          const rawText = ((s.category || "") + " " + (s.name || "") + " " + (s.id || "")).toLowerCase();
          const normText = removeAccents(rawText);
          return words.every(w => normText.includes(w) || rawText.includes(w));
        });
      }
      if (countSpan) {
        if (kw) {
          countSpan.innerHTML = '<span style="color:#10b981;"><i class="fa-solid fa-check"></i> ' + filtered.length + '/' + totalInProvider + ' SP</span>';
        } else {
          countSpan.innerHTML = '<span style="color:#94a3b8;">' + totalInProvider + ' SP</span>';
        }
      }
      const currentVal = sSel.value;
      let optionsHtml = '<option value="">-- ' + (kw ? ('Tìm thấy ' + filtered.length + ' SP (Bấm để chọn)') : ('Chọn sản phẩm nguồn (' + filtered.length + ' SP)')) + ' --</option>';
      optionsHtml += filtered.map(s => {
        const isSelected = String(s.id) === String(currentVal) ? ' selected="selected"' : '';
        const pPrice = Number(s.price || 0);
        const pStock = Number(s.amount || 0);
        const priceStr = (typeof formatVND === "function") ? formatVND(pPrice) : (pPrice.toLocaleString("vi-VN") + " đ");
        return '<option value="' + s.id + '" data-price="' + pPrice + '" data-stock="' + pStock + '"' + isSelected + '>' +
          '[' + (s.category || provider) + '] ' + s.name + ' - ' + priceStr + ' (Tồn: ' + pStock.toLocaleString() + ')' +
        '</option>';
      }).join("");
      sSel.innerHTML = optionsHtml;
      if (kw && filtered.length === 1 && !sSel.value) {
        sSel.value = String(filtered[0].id);
      }
      if (typeof handleAdmModalSourceChange === "function") handleAdmModalSourceChange();
    }
    window.filterAdmModalSourceProducts = filterAdmModalSourceProducts;
