      let bits = "";
      for (let i = 0; i < clean.length; i++) {
        const val = base32chars.indexOf(clean[i]);
        if (val === -1) continue;
        bits += val.toString(2).padStart(5, "0");
      }
      const bytes = new Uint8Array(Math.floor(bits.length / 8));
