        const existingIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === email);
        const existingUser = existingIdx !== -1 ? users[existingIdx] : null;
        name = name || (existingUser && existingUser.name) || email.split("@")[0];
        picture = picture || (existingUser && existingUser.avatar) || ("https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email));
        const isAdm = (typeof isAdminUser === "function") ? isAdminUser({ email: email }) : (email === ROOT_ADMIN_EMAIL.toLowerCase());
        const role = isAdm ? "Quản Trị Viên" : ((existingUser && existingUser.role) || "Thành Viên");
        const initBalance = (existingUser && existingUser.balance !== undefined) ? Number(existingUser.balance) : 0;
        currentUser = {
          userId: (existingUser && existingUser.userId) || ("USR_" + Math.floor(100000 + Math.random() * 900000)),
          name: name,
          email: email,
          role: role,
          balance: initBalance,
          avatar: picture
        };
        const savedRefCode = (localStorage.getItem("mmo_ref_code") || sessionStorage.getItem("mmo_ref_code") || "").trim().toLowerCase();
        if (savedRefCode && savedRefCode !== email && savedRefCode !== email.split("@")[0]) {
          currentUser.referredBy = (existingUser && existingUser.referredBy) ? existingUser.referredBy : savedRefCode;
        }
        if (existingIdx !== -1) {
          users[existingIdx] = Object.assign({}, users[existingIdx], currentUser);
        } else {
          users.unshift(Object.assign({}, currentUser, { created: new Date().toLocaleDateString("vi-VN") }));
        }
