        tabAdmWithdrawals: "tabBtnAdmWithdrawals",
        tabAdmTxLogs: "tabBtnAdmTxLogs",
        tabAdmOrders: "tabBtnAdmOrders",
        tabAdmPayment: "tabBtnAdmPayment",
        tabAdmGeneral: "tabBtnAdmGeneral",
        tabAdmAdmins: "tabBtnAdmAdmins",
