    async function executeSourceApiCall(action, payload) {
      payload = payload || {};
      const provider = (payload && payload.provider) ? String(payload.provider).toLowerCase() : "sellmmo";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : (API_SOURCES ? API_SOURCES.sellmmo : {});
      const baseUrl = (payload && payload.baseUrl) ? String(payload.baseUrl).trim() : (pCfg.baseUrl || "https://sellmmo.vn");
      const apiKey = (payload && payload.apiKey) ? String(payload.apiKey).trim() : (pCfg.apiKey || "");
      const workerProxy = (typeof sourceProxyUrl !== "undefined" && sourceProxyUrl) ? sourceProxyUrl.replace(/\/+$/, "") : "https://mmo-api-proxy.manhdongvtc.workers.dev";
      if (pCfg.authType === "userpass") {
        const uname = pCfg.username || "";
        const upass = pCfg.password || "";
        const bUrl = baseUrl.replace(/\/+$/, "");
        if (action === "getProfile") {
          const target = bUrl + "/api/GetBalance.php?username=" + encodeURIComponent(uname) + "&password=" + encodeURIComponent(upass);
          try {
            const resp = await fetch(workerProxy + "?url=" + encodeURIComponent(target));
            const rawText = await resp.text();
            let money = 0;
            let isOk = false;
            try {
              const json = JSON.parse(rawText);
              if (json && (json.status === "success" || json.data)) {
                money = Number(json.data.balance || json.data.money || json.data.Balance || json.money || 0);
                isOk = true;
              }
            } catch(jsonErr) {
              const digits = rawText.replace(/\D/g, '');
              if (digits) {
                money = parseInt(digits, 10);
                isOk = true;
              }
            }
            return { success: isOk, data: { money: money }, provider: provider, raw: rawText };
          } catch(e) {
            console.warn("shop1989nd getProfile error:", e);
            return { success: false, data: { money: 0 }, provider: provider };
          }
        }
        if (action === "getProducts") {
          const target = bUrl + "/api/ListResource.php?username=" + encodeURIComponent(uname) + "&password=" + encodeURIComponent(upass);
          try {
            const resp = await fetch(workerProxy + "?url=" + encodeURIComponent(target));
            const json = await resp.json();
            let categories = [];
            if (json.status === "success" && Array.isArray(json.categories)) {
              categories = json.categories.map(function(cat) {
                return {
                  id: cat.id,
                  name: cat.name,
                  products: (cat.products || cat.accounts || []).map(function(p) {
                    return { id: p.id, name: p.name, price: Number(p.price || 0), amount: Number(p.amount || p.accounts || 0) };
                  })
                };
              });
            } else if (json.status === "success" && Array.isArray(json.data)) {
              categories = [{ id: 0, name: "Tất cả sản phẩm", products: json.data.map(function(p) {
                return { id: p.id, name: p.name, price: Number(p.price || 0), amount: Number(p.amount || p.accounts || 0) };
              }) }];
            }
            return { success: json.status === "success", categories: categories, provider: provider, raw: json };
          } catch(e) {
            console.warn("shop1989nd getProducts error:", e);
            return { success: false, categories: [], provider: provider };
          }
        }
        if (action === "buyProduct") {
          const prodId = payload.productId || payload.id;
          const amount = payload.amount || 1;
          const target = bUrl + "/api/BResource.php?username=" + encodeURIComponent(uname) + "&password=" + encodeURIComponent(upass) + "&id=" + encodeURIComponent(prodId) + "&amount=" + encodeURIComponent(amount);
          try {
            const resp = await fetch(workerProxy + "?url=" + encodeURIComponent(target));
            const json = await resp.json();
            let accounts = [];
            if (json.status === "success" && json.data) {
              if (Array.isArray(json.data.lists)) {
                accounts = json.data.lists.map(function(it) {
                  if (typeof it === "object" && it) return (it.account || it.data || JSON.stringify(it)).trim();
                  return String(it).trim();
                }).filter(Boolean);
              } else if (Array.isArray(json.data)) {
                accounts = json.data.map(function(it) {
                  if (typeof it === "object" && it) return (it.account || it.data || JSON.stringify(it)).trim();
                  return String(it).trim();
                }).filter(Boolean);
              }
            }
            if (json.status !== "success" || accounts.length === 0) {
              return { success: false, message: json.msg || "Mua hàng từ shop1989nd thất bại!", raw: json };
            }
            if (payload.targetProdId && typeof callGasApi === "function") {
              callGasApi("adminAddStock", {
                prodId: payload.targetProdId,
                accountsStr: accounts.join("\n"),
                note: "Nhập tự động shop1989nd trans: " + (json.data && json.data.trans_id ? json.data.trans_id : "")
              }).catch(function(e) { console.log("Ghi sheet kho:", e); });
            }
            return {
              success: true,
              message: "Mua hàng từ shop1989nd thành công!",
              trans_id: (json.data && json.data.trans_id) ? json.data.trans_id : "",
              accounts: accounts,
              count: accounts.length,
              provider: provider,
              raw: json
            };
          } catch(e) {
            console.warn("shop1989nd buyProduct error:", e);
            return { success: false, message: "Lỗi kết nối shop1989nd!", provider: provider };
          }
        }
        return { success: false, message: "Hành động không hỗ trợ cho shop1989nd" };
      }
      if (action === "getProfile") {
        const target = baseUrl.replace(/\/+$/, "") + "/api/profile.php?api_key=" + encodeURIComponent(apiKey);
        try {
          const resp = await fetch(workerProxy + "?url=" + encodeURIComponent(target));
          const json = await resp.json();
          return {
            success: json.status === "success",
            data: json.data || {},
            provider: provider,
            raw: json
          };
        } catch(workerErr) {
          console.warn("Worker proxy error, fallback to GAS:", workerErr);
          return await callGasApi("apiSourceGetProfile", payload);
        }
      }
      if (action === "getProductStock") {
        try {
          const prodsRes = await executeSourceApiCall("getProducts", payload);
          if (prodsRes && prodsRes.success && Array.isArray(prodsRes.categories)) {
            let foundAmount = null;
            prodsRes.categories.forEach(cat => {
              (cat.products || []).forEach(p => {
                if (String(p.id) === String(payload.sourceProdId || payload.id)) {
                  foundAmount = Number(p.amount) || 0;
                }
              });
            });
            if (foundAmount !== null) {
              return { success: true, amount: foundAmount, provider: provider };
            }
          }
        } catch(err) {
          console.warn("getProductStock error:", err);
        }
        return { success: false, amount: 0, provider: provider };
      }
      if (action === "getProducts") {
        const target = baseUrl.replace(/\/+$/, "") + "/api/products.php?api_key=" + encodeURIComponent(apiKey);
        try {
          const resp = await fetch(workerProxy + "?url=" + encodeURIComponent(target));
          const json = await resp.json();
          return {
            success: json.status === "success",
            categories: json.categories || [],
            provider: provider,
            raw: json
          };
        } catch(workerErr) {
          console.warn("Worker proxy error, fallback to GAS:", workerErr);
          return await callGasApi("apiSourceGetProducts", payload);
        }
      }
      if (action === "buyProduct") {
        const target = baseUrl.replace(/\/+$/, "") + "/api/buy_product";
        const bodyStr = "api_key=" + encodeURIComponent(apiKey) +
                        "&action=buyProduct&id=" + encodeURIComponent(payload.productId || payload.id) +
                        "&amount=" + encodeURIComponent(payload.amount || 1) +
                        (payload.coupon ? ("&coupon=" + encodeURIComponent(payload.coupon)) : "");
        try {
          const resp = await fetch(workerProxy + "?url=" + encodeURIComponent(target), {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: bodyStr
          });
          const json = await resp.json();
          let accounts = [];
          if (Array.isArray(json.data)) {
            accounts = json.data.map(it => (typeof it === "object" && it) ? (it.account || it.data || JSON.stringify(it)) : String(it).trim()).filter(Boolean);
          } else if (typeof json.data === "string" && json.data.trim()) {
            accounts = json.data.trim().split(/\r?\n/).map(s => s.trim()).filter(Boolean);
          } else if (Array.isArray(json.accounts)) {
            accounts = json.accounts.map(it => (typeof it === "object" && it) ? (it.account || it.data || JSON.stringify(it)) : String(it).trim()).filter(Boolean);
          } else if (typeof json.accounts === "string" && json.accounts.trim()) {
            accounts = json.accounts.trim().split(/\r?\n/).map(s => s.trim()).filter(Boolean);
          }
          if (json.status !== "success" || accounts.length === 0) {
            return {
              success: false,
              message: json.msg || "Mua hàng từ nguồn thất bại hoặc hết số dư trên hệ thống!",
              raw: json
            };
          }
          if (payload.targetProdId && typeof callGasApi === "function") {
            callGasApi("adminAddStock", {
              prodId: payload.targetProdId,
              accountsStr: accounts.join("\n"),
              note: "Nhập tự động Worker " + provider + " trans: " + (json.trans_id || "")
            }).catch(function(e) { console.log("Ghi sheet kho:", e); });
          }
          return {
            success: true,
            message: "Mua hàng từ nguồn thành công!",
            trans_id: json.trans_id || "",
            accounts: accounts,
            count: accounts.length,
            provider: provider,
            raw: json
          };
        } catch(workerErr) {
          console.warn("Worker proxy error, fallback to GAS:", workerErr);
          return await callGasApi("apiSourceBuyProduct", payload);
        }
      }
      return { success: false, message: "Hành động không hợp lệ" };
    }
