      const PAGE_SIZE = 10;
      let curPage = (typeof paginationState !== "undefined" && paginationState.admApiMappings) ? paginationState.admApiMappings : 1;
      const totalPages = Math.ceil(filteredProds.length / PAGE_SIZE) || 1;
