          '[' + (src.category || provider) + '] ' + src.name + ' - ' + (typeof formatVND === "function" ? formatVND(src.price) : src.price) + ' (Tồn: ' + (Number(src.amount) || 0).toLocaleString() + ')' +
        '</option>';
