    async function callGasApi(action, params = {}) {
      const apiUrl = getBackendApiUrl();
      if (!apiUrl) return null;
      const isMutation = [
        "adminSaveProduct", "adminDeleteProduct", "adminSaveSettings",
        "adminUpdateUserRole", "adminDeleteStockItem", "adminImportStock", "createOrder",
        "authGoogle", "authEmail", "verifyAdminPin", "payOrderByWallet",
        "apiSourceBuyProduct", "apiSourceGetProfile", "apiSourceGetProducts", "sendChatMessage", "markChatRead",
        "adminUpdateBalance", "adminUpdateOrderStatus"
      ].includes(action);
      const timeoutMs = isMutation ? 30000 : 25000;
      function createTimeoutSignal(ms) {
        if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
          return AbortSignal.timeout(ms);
        }
        const controller = new AbortController();
        setTimeout(() => controller.abort(), ms);
        return controller.signal;
      }
      if (isMutation) {
        try {
          const res = await fetch(apiUrl, {
            method: "POST",
            headers: { "Content-Type": "text/plain;charset=utf-8" },
            body: JSON.stringify({ action, ...params }),
            signal: createTimeoutSignal(timeoutMs)
          });
          return await res.json();
        } catch (err) {
          console.warn("GAS POST error:", err);
          return null;
        }
      }
      try {
        const queryParams = new URLSearchParams();
        queryParams.append("action", action);
        for (const k in params) {
          if (params[k] !== undefined && params[k] !== null) {
            queryParams.append(k, typeof params[k] === "object" ? JSON.stringify(params[k]) : params[k]);
          }
        }
        const url = apiUrl + (apiUrl.includes("?") ? "&" : "?") + queryParams.toString();
        const res = await fetch(url, { method: "GET", signal: createTimeoutSignal(timeoutMs) });
        return await res.json();
      } catch (err) {
        try {
          const res = await fetch(apiUrl, {
            method: "POST",
            headers: { "Content-Type": "text/plain;charset=utf-8" },
            body: JSON.stringify({ action, ...params }),
            signal: createTimeoutSignal(timeoutMs)
          });
          return await res.json();
        } catch (err2) {
          console.warn("GAS API fallback error:", err2);
          return null;
        }
      }
    }
