  async function handleConfirmDirectPayment() {
    if (!window._pendingDirectOrder) {
      showToast("Không tìm thấy thông tin đơn hàng cần thanh toán!", "warning");
      return;
    }
    const btn = document.getElementById("btnDpConfirmPayment");
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang xuất tài khoản từ kho Turso...";
    }
    const emailInp = document.getElementById("dpModalEmail");
    const buyerEmail = (emailInp ? emailInp.value.trim() : "") || ((typeof currentUser !== "undefined" && currentUser) ? currentUser.email : ("guest_" + Date.now() + "@gmail.com"));
    try {
      await completeOrderDelivery(window._pendingDirectOrder, buyerEmail);
      closeModal("directPaymentModal");
      window._pendingDirectOrder = null;
    } catch(err) {
      showToast("Lỗi giao hàng: " + err.message, "danger");
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = "<i class='fa-solid fa-circle-check'></i> Tôi Đã Thanh Toán &amp; Nhận Tài Khoản";
      }
    }
  }
