    function generateGmailDotTrick() {
      const rawInput = document.getElementById("inputGmailDot") ? document.getElementById("inputGmailDot").value.trim() : "";
      if (!rawInput) {
        if (typeof showToast === "function") showToast("Vui lòng nhập địa chỉ Gmail!", "warning");
        return;
      }
      let cleanUser = rawInput.toLowerCase();
      if (cleanUser.includes("@")) {
        cleanUser = cleanUser.split("@")[0].trim();
      }
      cleanUser = cleanUser.replace(/\./g, "").split("+")[0].replace(/[^a-z0-9]/g, "");
      if (cleanUser.length < 2) {
        if (typeof showToast === "function") showToast("Tên Gmail quá ngắn để tạo Dot Trick (tối thiểu 2 ký tự)!", "warning");
        return;
      }
      if (cleanUser.length > 30) {
        cleanUser = cleanUser.substring(0, 30);
      }
      const maxLimit = parseInt(document.getElementById("gmailDotLimit") ? document.getElementById("gmailDotLimit").value : "500") || 500;
      const includeGooglemail = document.getElementById("gmailDotGooglemail") ? document.getElementById("gmailDotGooglemail").checked : true;
      const includePlus = document.getElementById("gmailDotPlus") ? document.getElementById("gmailDotPlus").checked : false;
      const results = [];
      const chars = cleanUser.split("");
      const n = chars.length;
      const numGaps = n - 1;
      const totalCombos = Math.pow(2, numGaps);
      const combosToGenerate = Math.min(totalCombos, maxLimit);
      for (let i = 0; i < combosToGenerate; i++) {
        let emailUser = chars[0];
        for (let j = 0; j < numGaps; j++) {
          if ((i & (1 << j)) !== 0) {
            emailUser += ".";
          }
          emailUser += chars[j + 1];
        }
        results.push(emailUser + "@gmail.com");
        if (includeGooglemail && results.length < maxLimit * 2) {
          results.push(emailUser + "@googlemail.com");
        }
      }
      if (includePlus) {
        const plusTags = ["1", "2", "3", "sub", "mmo", "vip", "order", "acc"];
        plusTags.forEach(tag => {
          results.push(cleanUser + "+" + tag + "@gmail.com");
          if (includeGooglemail) {
            results.push(cleanUser + "+" + tag + "@googlemail.com");
          }
        });
      }
      const uniqueResults = Array.from(new Set(results));
      const outputEl = document.getElementById("outputGmailDot");
      if (outputEl) {
        outputEl.value = uniqueResults.join("\n");
      }
      const statTotal = document.getElementById("gmailDotStatTotal");
      if (statTotal) statTotal.innerText = uniqueResults.length.toLocaleString("vi-VN");
      const statRoot = document.getElementById("gmailDotStatRoot");
      if (statRoot) statRoot.innerText = cleanUser + "@gmail.com";
      if (typeof showToast === "function") {
        showToast("🎉 Đã tạo thành công " + uniqueResults.length + " biến thể Gmail Dot Trick!", "success");
      }
    }
    window.generateGmailDotTrick = generateGmailDotTrick;
