    function extractFirstTarget(rawLine) {
      if (!rawLine) return "";
      let line = rawLine.trim();
      if (line.includes("|")) line = line.split("|")[0].trim();
      if (line.includes(" ")) line = line.split(" ")[0].trim();
      if (line.includes("tiktok.com/@")) {
        line = line.split("tiktok.com/@")[1].split(/[/?#]/)[0];
      } else if (line.startsWith("@")) {
        line = line.substring(1);
      }
      if (line.includes("facebook.com/")) {
        line = line.split("facebook.com/")[1].split(/[/?#]/)[0];
        if (line === "profile.php" && rawLine.includes("id=")) {
          const matchId = rawLine.match(/id=(\d+)/);
          if (matchId) line = matchId[1];
        }
      }
      return line.replace(/[^a-zA-Z0-9._-]/g, "").trim();
    }
    function parseInputLines(text) {
      if (!text) return [];
      const normalized = text.replace(/\n/g, "\n").replace(/\r/g, "\n");
      return normalized.split("\n")
        .map(l => l.trim())
        .filter(l => l.length > 0);
    }
    async function checkSingleFbUser(uid) {
      if (!uid || uid.length < 2) return false;
      if (/\b(die|banned|checkpoint|disabled|suspended|khoa)\b/i.test(uid)) {
        return false;
      }
      if (/^\d+$/.test(uid)) {
        return new Promise((resolve) => {
          let isDone = false;
          const img = new Image();
          const timer = setTimeout(() => {
            if (!isDone) {
              isDone = true;
              resolve(true);
            }
          }, 3500);
          img.onload = function() {
            if (!isDone) {
              isDone = true;
              clearTimeout(timer);
              resolve(img.naturalWidth > 1);
            }
          };
          img.onerror = function() {
            if (!isDone) {
              isDone = true;
              clearTimeout(timer);
              resolve(false);
            }
          };
          img.src = "https://graph.facebook.com/" + encodeURIComponent(uid) + "/picture?type=normal&t=" + Date.now();
        });
      }
      return new Promise((resolve) => {
        let isDone = false;
        const img = new Image();
        const timer = setTimeout(() => {
          if (!isDone) {
            isDone = true;
            resolve(true);
          }
        }, 3000);
        img.onload = function() {
          if (!isDone) {
            isDone = true;
            clearTimeout(timer);
            resolve(true);
          }
        };
        img.onerror = function() {
          if (!isDone) {
            isDone = true;
            clearTimeout(timer);
            resolve(true);
          }
        };
        img.src = "https://graph.facebook.com/" + encodeURIComponent(uid) + "/picture?type=normal&t=" + Date.now();
      });
    }
    async function runCheckFbLive() {
      const text = (document.getElementById("fbLiveInput") ? document.getElementById("fbLiveInput").value : "").trim();
      if (!text) {
        showToast("Vui lòng nhập danh sách UID Facebook", "warning");
        return;
      }
      const rawLines = parseInputLines(text);
      if (rawLines.length === 0) {
        showToast("Vui lòng nhập ít nhất 1 UID Facebook!", "warning");
        return;
      }
      const totalCount = rawLines.length;
      showToast("Đang kiểm tra " + totalCount + " tài khoản Facebook...", "success");
      let liveList = [];
      let dieList = [];
      const batchSize = 4;
      for (let i = 0; i < rawLines.length; i += batchSize) {
        const chunk = rawLines.slice(i, i + batchSize);
        await Promise.all(chunk.map(async (line) => {
          const uid = extractFirstTarget(line);
          if (!uid) return;
          const isLive = await checkSingleFbUser(uid);
          if (isLive) {
            liveList.push(line);
          } else {
            dieList.push(line);
          }
        }));
        document.getElementById("fbStatTotal").innerText = totalCount;
        document.getElementById("fbStatLive").innerText = liveList.length;
        document.getElementById("fbStatDie").innerText = dieList.length;
        document.getElementById("fbLiveOutput").value = liveList.join("\n");
        document.getElementById("fbDieOutput").value = dieList.join("\n");
        if (i + batchSize < rawLines.length) {
          await new Promise(r => setTimeout(r, 60));
        }
      }
      showToast("Đã check xong FB: " + liveList.length + " LIVE, " + dieList.length + " DIE", "success");
    }
