    let isTtLiveChecking = false;
    function extractTikTokTarget(rawLine) {
      if (!rawLine) return "";
      let line = String(rawLine).trim();
      if (!line) return "";
      const urlMatch = line.match(/tiktok\.com\/@([a-zA-Z0-9._-]+)/i);
      if (urlMatch && urlMatch[1]) {
        return urlMatch[1].trim();
      }
      const token = line.split(/[\s|,:;\t]+/)[0].trim();
      return token.replace(/^@+/, '').replace(/[^a-zA-Z0-9._-]/g, '').trim();
    }
    async function checkSingleTikTokUser(user, retryCount = 1) {
      if (!user || user.length < 2) return false;
      if (/\b(die|banned|suspended|khoa|block)\b/i.test(user)) {
        return false;
      }
      for (let attempt = 0; attempt <= retryCount; attempt++) {
        try {
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 4000);
          const oembedUrl = 'https://www.tiktok.com/oembed?url=' + encodeURIComponent('https://www.tiktok.com/@' + user);
          const res = await fetch(oembedUrl, {
            method: 'GET',
            signal: controller.signal,
            headers: { 'Accept': 'application/json' }
          });
          clearTimeout(timeoutId);
          if (res.ok) {
            const data = await res.json();
            if (data && (data.author_name || data.title || data.type === 'rich' || data.type === 'video')) {
              return true;
            }
          }
          if (res.status === 400 || res.status === 404) {
            return false;
          }
        } catch (e) {
          if (attempt < retryCount) {
            await new Promise(r => setTimeout(r, 200));
            continue;
          }
        }
      }
      return false;
    }
    async function runCheckTtLive() {
      if (isTtLiveChecking) {
        showToast("Đang trong quá trình kiểm tra, vui lòng đợi!", "warning");
        return;
      }
      const inputEl = document.getElementById("ttLiveInput");
      const text = (inputEl ? inputEl.value : "").trim();
      if (!text) {
        showToast("Vui lòng nhập danh sách TikTok (Username/Link)", "warning");
        return;
      }
      const rawLines = parseInputLines(text);
      if (rawLines.length === 0) {
        showToast("Vui lòng nhập ít nhất 1 tài khoản TikTok!", "warning");
        return;
      }
      const totalCount = rawLines.length;
      isTtLiveChecking = true;
      const btnRun = document.querySelector("#toolTtLive .btn-tool-run");
      const origBtnHtml = btnRun ? btnRun.innerHTML : "";
      if (btnRun) {
        btnRun.disabled = true;
        btnRun.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang Check (0/" + totalCount + ")...";
      }
      showToast("Đang kiểm tra " + totalCount + " tài khoản TikTok...", "info");
      let liveList = [];
      let dieList = [];
      document.getElementById("ttStatTotal").innerText = totalCount;
      document.getElementById("ttStatLive").innerText = "0";
      document.getElementById("ttStatDie").innerText = "0";
      document.getElementById("ttLiveOutput").value = "";
      document.getElementById("ttDieOutput").value = "";
      const batchSize = 3;
      let checkedCount = 0;
      try {
        for (let i = 0; i < rawLines.length; i += batchSize) {
          const chunk = rawLines.slice(i, i + batchSize);
          await Promise.all(chunk.map(async (line) => {
            const user = extractTikTokTarget(line);
            if (!user || user.length < 2) {
              dieList.push(line);
              return;
            }
            const isLive = await checkSingleTikTokUser(user);
            if (isLive) {
              liveList.push(line);
            } else {
              dieList.push(line);
            }
          }));
          checkedCount = Math.min(totalCount, checkedCount + chunk.length);
          if (btnRun) {
            btnRun.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang Check (" + checkedCount + "/" + totalCount + ")...";
          }
          document.getElementById("ttStatLive").innerText = liveList.length;
          document.getElementById("ttStatDie").innerText = dieList.length;
          document.getElementById("ttLiveOutput").value = liveList.join("\n");
          document.getElementById("ttDieOutput").value = dieList.join("\n");
          if (i + batchSize < rawLines.length) {
            await new Promise(r => setTimeout(r, 80));
          }
        }
        showToast("Đã check xong TikTok: " + liveList.length + " LIVE, " + dieList.length + " DIE", "success");
      } catch (err) {
        console.error("Lỗi khi check TikTok:", err);
        showToast("Đã xảy ra lỗi khi kiểm tra TikTok: " + (err.message || err), "error");
      } finally {
        isTtLiveChecking = false;
        if (btnRun) {
          btnRun.disabled = false;
          btnRun.innerHTML = origBtnHtml || "<i class='fa-solid fa-play'></i> Bắt Đầu Check TikTok";
        }
      }
    }
