    function rejectWithdrawRequest(wdId) {
      const list = getWithdrawRequests();
      const item = list.find(w => w.id === wdId);
      if (!item) {
        showToast("Không tìm thấy yêu cầu rút tiền này!", "danger");
        return;
      }
      if (item.status !== "Chờ Duyệt") {
        showToast("Yêu cầu này đã được xử lý trước đó!", "warning");
        return;
      }
      const reason = prompt("Nhập lý do từ chối yêu cầu rút tiền (Số tiền " + formatVND(item.amount) + " sẽ được HOÀN LẠI vào ví người dùng):", "Thông tin tài khoản ngân hàng không chính xác");
      if (reason === null) return;
      const adminName = currentUser ? (currentUser.name + " (" + currentUser.email + ")") : "Quản Trị Viên";
      item.status = "Đã từ chối (Hoàn tiền)";
      item.handledBy = adminName;
      item.rejectReason = reason || "Từ chối bởi Admin";
      item.handledTime = new Date().toLocaleDateString("vi-VN") + " " + new Date().toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });
      saveWithdrawRequests(list);
      const users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase() === (item.userEmail || "").toLowerCase());
      let newBal = 0;
      if (uIdx !== -1) {
        users[uIdx].balance = (users[uIdx].balance || 0) + item.amount;
        newBal = users[uIdx].balance;
        saveRegisteredUsers(users);
      }
      if (currentUser && currentUser.email.toLowerCase() === item.userEmail.toLowerCase()) {
        currentUser.balance = newBal;
        localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        updateUserUI();
      }
      recordTransaction(item.userEmail, item.userName, "Hoàn tiền rút (Từ chối)", item.amount, newBal, "Từ chối bởi Admin " + adminName + " - Lý do: " + (reason || "Thông tin không hợp lệ"));
      renderAdminWithdrawTable();
      renderAdminUsersTable();
      renderAdminTxTable();
      showToast("Đã từ chối và hoàn tiền " + formatVND(item.amount) + " lại vào ví người dùng!", "info");
    }
    function toggleLockUser(email) {
      const rootEmail = (typeof ROOT_ADMIN_EMAIL !== "undefined" ? ROOT_ADMIN_EMAIL : "manhdongvtc@gmail.com").toLowerCase().trim();
      if (email.toLowerCase().trim() === rootEmail) {
        showToast("Không thể khóa tài khoản Root Admin!", "warning");
        return;
      }
      if (currentUser && currentUser.email.toLowerCase().trim() === email.toLowerCase().trim()) {
        showToast("Bạn không thể tự khóa tài khoản của chính mình!", "warning");
        return;
      }
      let users = getRegisteredUsers();
      const idx = users.findIndex(u => (u.email || "").toLowerCase() === email.toLowerCase());
      if (idx === -1) {
        showToast("Không tìm thấy người dùng!", "danger");
        return;
      }
      users[idx].isLocked = !users[idx].isLocked;
      saveRegisteredUsers(users);
      renderAdminUsersTable();
      if (users[idx].isLocked) {
        showToast("🔒 Đã khóa tài khoản: " + users[idx].name, "warning");
      } else {
        showToast("🔓 Đã mở khóa tài khoản: " + users[idx].name, "success");
      }
    }
    function deleteUser(email) {
      const rootEmail = (typeof ROOT_ADMIN_EMAIL !== "undefined" ? ROOT_ADMIN_EMAIL : "manhdongvtc@gmail.com").toLowerCase().trim();
      const targetEmail = (email || "").toLowerCase().trim();
      if (targetEmail === rootEmail) {
        showToast("Không thể xóa tài khoản Root Admin tối cao!", "warning");
        return;
      }
      let isSelf = (currentUser && (currentUser.email || "").toLowerCase().trim() === targetEmail);
      let confirmMsg = "Bạn có chắc chắn muốn XÓA vĩnh viễn tài khoản [" + email + "] khỏi hệ thống?";
      if (isSelf) {
        confirmMsg = "CẢNH BÁO: Bạn đang đăng nhập bằng tài khoản [" + email + "]. Nếu xóa, bạn sẽ bị đăng xuất ngay lập tức. Tiếp tục xóa?";
      }
      if (!confirm(confirmMsg)) {
        return;
      }
      let users = getRegisteredUsers();
      users = users.filter(u => (u.email || "").toLowerCase().trim() !== targetEmail);
      localStorage.setItem("mmo_registered_users", JSON.stringify(users));
      let adminList = getAdminEmails();
      if (adminList.map(e => (e || "").toLowerCase().trim()).includes(targetEmail)) {
        adminList = adminList.filter(e => (e || "").toLowerCase().trim() !== targetEmail);
        saveAdminEmails(adminList);
      }
      try {
        if (typeof callGasApi === "function") {
          callGasApi("adminDeleteUser", {
            email: targetEmail,
            adminEmail: (currentUser ? currentUser.email : ROOT_ADMIN_EMAIL)
          }).catch(function(e) {});
        }
      } catch(e) {}
      if (isSelf) {
        localStorage.removeItem("mmo_user");
        currentUser = null;
        updateUserUI();
        switchView("viewStore");
        showToast("Đã xóa tài khoản và đăng xuất!", "info");
      } else {
        if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
        if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
        if (typeof renderAdminDashboard === "function") renderAdminDashboard();
        showToast("🗑️ Đã xóa vĩnh viễn tài khoản: " + email, "success");
      }
    }
    window.deleteUser = deleteUser;
    function openWithdrawModal() {
      if (!currentUser) {
        showToast("Vui lòng đăng nhập để rút tiền!", "info");
        openAuthModal();
        return;
      }
      const bal = currentUser.balance || 0;
      const balDisp = document.getElementById("withdrawModalCurrentBal");
      if (balDisp) balDisp.innerText = formatVND(bal);
      try {
        const savedBank = localStorage.getItem("mmo_user_bank");
        if (savedBank) {
          const b = JSON.parse(savedBank);
          if (document.getElementById("withdrawBankNameInput")) document.getElementById("withdrawBankNameInput").value = b.bankName || "";
          if (document.getElementById("withdrawBankAccInput")) document.getElementById("withdrawBankAccInput").value = b.bankAcc || "";
          if (document.getElementById("withdrawBankOwnerInput")) document.getElementById("withdrawBankOwnerInput").value = b.bankOwner || "";
        }
      } catch(e) {}
      if (document.getElementById("withdrawAmountInput")) {
        document.getElementById("withdrawAmountInput").value = Math.min(bal, 100000) || "";
      }
      document.getElementById("withdrawModal").style.display = "flex";
    }
    function handleProfileWithdraw() {
      openWithdrawModal();
    }
    function submitWithdrawRequest() {
      if (!currentUser) {
        showToast("Vui lòng đăng nhập để rút tiền!", "warning");
        return;
      }
      const amount = parseInt(document.getElementById("withdrawAmountInput")?.value) || 0;
      const bankName = document.getElementById("withdrawBankNameInput")?.value.trim();
      const bankAcc = document.getElementById("withdrawBankAccInput")?.value.trim();
      const bankOwner = document.getElementById("withdrawBankOwnerInput")?.value.trim();
      const note = document.getElementById("withdrawNoteInput")?.value.trim() || "Rút tiền về tài khoản ngân hàng";
      if (amount < 50000) {
        showToast("Số tiền rút tối thiểu là 50.000 đ!", "warning");
        return;
      }
      if (amount > (currentUser.balance || 0)) {
        showToast("Số dư ví không đủ để rút số tiền này!", "danger");
        return;
      }
      if (!bankName || !bankAcc || !bankOwner) {
        showToast("Vui lòng điền đầy đủ Ngân hàng, Số tài khoản và Tên chủ tài khoản!", "warning");
        return;
      }
      localStorage.setItem("mmo_user_bank", JSON.stringify({ bankName, bankAcc, bankOwner }));
      currentUser.balance -= amount;
      localStorage.setItem("mmo_user", JSON.stringify(currentUser));
      let users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase() === currentUser.email.toLowerCase());
      if (uIdx !== -1) {
        users[uIdx].balance = currentUser.balance;
        saveRegisteredUsers(users);
      }
      const wdList = getWithdrawRequests();
      const wdId = "WD" + Math.floor(100000 + Math.random() * 900000);
      const now = new Date();
      const timeStr = now.toLocaleDateString("vi-VN") + " " + now.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });
      wdList.unshift({
        id: wdId,
        userEmail: currentUser.email,
        userName: currentUser.name,
        amount: amount,
        bankName: bankName,
        bankAcc: bankAcc,
        bankOwner: bankOwner,
        time: timeStr,
        status: "Chờ Duyệt",
        handledBy: "",
        note: note
      });
      saveWithdrawRequests(wdList);
      recordTransaction(currentUser.email, currentUser.name, "Yêu cầu rút tiền", -amount, currentUser.balance, "Đang chờ duyệt | STK: " + bankAcc + " (" + bankName + ")");
      updateUserUI();
      closeModal("withdrawModal");
      renderUserWalletTransactions();
      if (typeof renderAdminWithdrawTable === "function") renderAdminWithdrawTable();
      if (typeof renderAdminTxTable === "function") renderAdminTxTable();
      showToast("🎉 Gửi yêu cầu rút " + formatVND(amount) + " thành công! Quản trị viên sẽ duyệt trong ít phút.", "success");
    }
    var ITEMS_PER_PAGE = 10;
