    window.renderAdminChatUI = renderAdminChatUI;
    function sendAdminChatReply() {
      if (!currentAdminChatTargetEmail) {
        showToast("Vui lòng chọn một cuộc trò chuyện từ danh sách bên trái trước!", "warning");
        return;
      }
      const inp = document.getElementById("admChatReplyInput");
      const text = (inp ? inp.value : "").trim();
      if (!text) return;
      const now = new Date();
      const adminName = (typeof currentUser !== "undefined" && currentUser && currentUser.name) ? currentUser.name : "Admin Quản Trị";
      const newMsg = {
        id: "ADM_" + Date.now().toString(36).toUpperCase() + "_" + Math.floor(Math.random() * 1000),
        sender: "admin",
        userEmail: currentAdminChatTargetEmail,
        senderName: adminName,
        text: text,
        time: now.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" }),
        date: now.toLocaleDateString("vi-VN"),
        timestamp: Date.now(),
        isReadByUser: false,
        isReadByAdmin: true
      };
      const all = getAllChatMessages();
      all.push(newMsg);
      saveAllChatMessages(all);
      if (inp) {
        inp.value = "";
        setTimeout(function() { if (inp) inp.focus(); }, 60);
      }
      renderAdminActiveStream(currentAdminChatTargetEmail);
      renderAdminChatList();
      playChatNotificationSound("send");
      broadcastChatMessage(newMsg);
      showToast("Đã gửi phản hồi hỗ trợ cho khách!", "success");
    }
